import type { ModeId } from '@lexpad/core';
import { useCanSpeak } from '@/lib/useCanSpeak.js';
import { useCurrentDay } from '@/lib/useCurrentDay.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { MODES_LOADING, blockerOf, loadModes, shownModes, type Blocker, type ModesView } from './data.js';
import { useCanListen } from './useCanListen.js';

/** What the games screen, Decks and Today know about the modes. */
export interface OpenModes {
  view: ModesView;
  /** The modes that can run here now, in the spec's order. */
  open: ModeId[];
  /** The modes switched on that cannot run here, each with the reason. */
  closed: { mode: ModeId; why: Blocker }[];
  /**
   * True once every switched-on mode has an answer: the notebook has been
   * read, and the device has said whether it can listen (Say it). Until
   * then "nothing can run" is not yet known to be true.
   */
  settled: boolean;
}

/**
 * The games and drills this notebook and this device can run right now:
 * switched on for the account (`shown`), fed by the notebook (`canFeed`),
 * with a voice for Dictation and a recogniser for Say it. The games screen
 * draws them, and Today and Decks count them, from the same answer, so they
 * never disagree.
 *
 * With every mode switched off (the flag off, or a server without SRS v2)
 * nothing is read beyond the flag: `loadModes` skips the words.
 */
export function useOpenModes(): OpenModes {
  const now = useCurrentDay();
  // An async querier, so Dexie follows every read past the first await.
  const view = useLiveQuery(async () => loadModes(now), MODES_LOADING, [now]);
  const lang = view.notebook?.targetLang ?? 'en';
  const canSpeak = useCanSpeak(lang);
  const shown = shownModes(view.srs);
  // Say it is offered only where the device can listen; asked once, and only when it is switched on.
  const canListen = useCanListen(shown.includes('sayIt'));
  if (!view.ready) return { view, open: [], closed: [], settled: false };
  // No notebook in view (the gate sends that account to onboarding): every
  // mode lacks words, which is what the games screen would say anyway.
  const words = view.notebook === undefined ? [] : view.words;
  const open: ModeId[] = [];
  const closed: { mode: ModeId; why: Blocker }[] = [];
  let settled = true;
  for (const mode of shown) {
    const why = blockerOf(mode, words, lang, { canSpeak, canListen });
    if (why === undefined) open.push(mode);
    else if (why === 'waiting') settled = false;
    else closed.push({ mode, why });
  }
  return { view, open, closed, settled };
}
